  // Options dans l'ordre des points (0 à 3). La page les mélange à l'affichage.
  questions: [
    {id: 'cr', axis: 'saisie', q: "Quand un commercial sort d'un rendez-vous, le compte rendu…", opts: [
      {t: "Reste dans son carnet ou dans sa tête", m: "Après un rendez-vous, le compte rendu reste dans la tête du commercial."},
