function diagPts(v){ var n = Math.round(Number(v)); return n >= 0 && n <= 3 ? n : 0; }
function diagInt(v, min, max){ var n = Math.round(Number(v)); return isFinite(n) ? Math.min(max, Math.max(min, n)) : min; }
function diagLevel(pct){
  if (pct >= DIAG.solid) return {name: 'Solide', tone: 'green'};
  if (pct >= DIAG.build) return {name: 'En construction', tone: 'amber'};
  return {name: 'À construire', tone: 'red'};
}
function diagAxisPct(ans, axisKey){
  var qs = DIAG.questions.filter(function(q){ return q.axis === axisKey; });
  var sum = 0;
  qs.forEach(function(q){ sum += diagPts(ans[q.id]); });
  return Math.round(sum / (3 * qs.length) * 100);
}
// Heures de ressaisie pré-remplies : plus la saisie et les flux sont faibles, plus on en perd.
function diagHours(ans){
  var pct = Math.round((diagAxisPct(ans, 'saisie') + diagAxisPct(ans, 'flux')) / 2);
  return pct < 35 ? 6 : pct < 60 ? 4 : pct < 85 ? 2 : 1;
}
// ans : { idQuestion: points 0-3 }. ctx : { people, hours }.
function diagCompute(ans, ctx){
  var axes = DIAG.axes.map(function(a){
    var pct = diagAxisPct(ans, a.key);
    return {key: a.key, label: a.label, pct: pct, level: diagLevel(pct)};
  });
  // Égalité : l'ordre des axes tranche (saisie, flux, auto, adoption).
  var sorted = axes.map(function(a, i){ return {a: a, i: i}; })
    .sort(function(x, y){ return x.a.pct - y.a.pct || x.i - y.i; })
    .map(function(x){ return x.a; });
  var weakest = sorted[0];
  var strongest = sorted[sorted.length - 1];
  var total = 0;
  var rows = DIAG.questions.map(function(q, i){ var p = diagPts(ans[q.id]); total += p; return {q: q, i: i, pts: p}; });
  // Où tu en es : jusqu'à 3 réponses notées 0 ou 1, la pire d'abord. Sinon les 3 plus basses.
  var low = rows.filter(function(r){ return r.pts <= 1; });
  var mirrors = (low.length ? low : rows).slice()
    .sort(function(x, y){ return x.pts - y.pts || x.i - y.i; })
    .slice(0, 3).map(function(r){ return r.q.opts[r.pts].m; });
  var people = diagInt(ctx.people, 1, 500);
  var hours = diagInt(ctx.hours, 0, 15);
  var profileKey = weakest.pct >= DIAG.solid ? 'solide' : weakest.key;
  return {
    axes: axes, weakest: weakest, strongest: strongest,
    score: Math.round(total / (3 * DIAG.questions.length) * 100),
    profileKey: profileKey, profile: DIAG.profiles[profileKey],
    recette: DIAG.profiles[weakest.key].recette,
    mirrors: mirrors,
    people: people, hours: hours,
    annual: people * hours * DIAG.weeks * DIAG.loaded,
    weekly: people * hours * DIAG.loaded
  };
}
/* DIAG:end */

const TONES = { green: '#3CC79A', amber: '#F1B24A', red: '#EF5D6F' };

const WEEKS = 47;
const LOADED = 45;

// Copie de calculateur/index.html (FREQ, bornes). À garder synchro si le calculateur change.
const FREQ = { jour: { perYear: WEEKS * 5, label: 'par jour' }, semaine: { perYear: WEEKS, label: 'par semaine' }, mois: { perYear: 11, label: 'par mois' } };

function esc(v) {
  return String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function int(v, min, max) {
  const n = Math.round(Number(v));
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : min;
}

function euro(n) {
  // Espace insécable classique : l'espace fine (U+202F) d'Intl disparaît dans certaines polices et clients mail.
  return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(n).replace(/ /g, ' ');
}

// ---------- Gabarit HTML (identité florianmarin.me : fond #1C1C1C, cartes #262626, accent #FF7A00, Montserrat)

const FONT = "Montserrat, 'Helvetica Neue', Arial, sans-serif";
